def shapes(g):
    seen=set(); out=[]
    for i in range(len(g)):
        for j in range(len(g[0])):
            if g[i][j] and (i,j) not in seen:
                c=g[i][j]; st=[(i,j)]; cells=set()
                while st:
                    a,b=st.pop()
                    if (a,b) in cells or not(0<=a<len(g) and 0<=b<len(g[0])) or g[a][b]!=c: continue
                    cells.add((a,b))
                    st += [(a+1,b),(a-1,b),(a,b+1),(a,b-1)]
                seen|=cells
                rs=[r for r,_ in cells]; cs=[c2 for _,c2 in cells]
                pat=[[c if (r,c2) in cells else 0 for c2 in range(min(cs),max(cs)+1)] for r in range(min(rs),max(rs)+1)]
                out.append({'c':c,'pat':pat,'r0':min(rs),'c0':min(cs)})
    return out

def is_frame(pat):
    # enclosed interior zero => frame
    h,w=len(pat),len(pat[0])
    return h>=3 and w>=3 and any(pat[i][j]==0 for i in range(1,h-1) for j in range(1,w-1))

def transform(g):
    h,w=len(g),len(g[0])
    out=[[0]*w for _ in range(h)]
    occ=[[False]*w for _ in range(h)]
    sh=shapes(g)
    frames=[s for s in sh if is_frame(s['pat'])]
    crosses=[s for s in sh if not is_frame(s['pat'])]
    def place(s, top):
        p=s['pat']; ph,pw=len(p),len(p[0])
        if top:
            for r in range(h-ph+1):
                if all(not occ[r+i][s['c0']+j] or p[i][j]==0 for i in range(ph) for j in range(pw) if p[i][j]):
                    break
        else:
            for r in range(h-ph,-1,-1):
                if all(not occ[r+i][s['c0']+j] or p[i][j]==0 for i in range(ph) for j in range(pw) if p[i][j]):
                    break
        for i in range(ph):
            for j in range(pw):
                if p[i][j]:
                    out[r+i][s['c0']+j]=p[i][j]; occ[r+i][s['c0']+j]=True
    for s in sorted(frames,key=lambda s:s['r0']): place(s,True)
    for s in sorted(crosses,key=lambda s:s['r0']): place(s,False)
    return out

