def is_frame(pat):
    h,w=len(pat),len(pat[0])
    # pad with border of ones (walls), flood from a border zero
    H,W=h+2,w+2
    grid=[[1]*W for _ in range(H)]
    for i in range(h):
        for j in range(w):
            grid[i+1][j+1]=pat[i][j]
    st=[(1,1)]; seen={(1,1)}
    while st:
        a,b=st.pop()
        for da,db in((1,0),(-1,0),(0,1),(0,-1)):
            x,y=a+da,b+db
            if 0<=x<H and 0<=y<W and grid[x][y]==0 and (x,y) not in seen:
                seen.add((x,y)); st.append((x,y))
    return any(grid[i][j]==0 and (i,j) not in seen for i in range(H) for j in range(W))

