def transform(g):
    h,w=len(g),len(g[0])
    out=[[0]*w for _ in range(h)]
    occ=[[False]*w for _ in range(h)]
    sh=shapes(g)
    frames=[s for s in sh if is_frame(s['pat'])]
    crosses=[s for s in sh if not is_frame(s['pat'])]
    def fits(r,s):
        p=s['pat']
        return all(not occ[r+i][s['c0']+j] for i in range(len(p)) for j in range(len(p[0])) if p[i][j])
    def put(r,s):
        p=s['pat']
        for i in range(len(p)):
            for j in range(len(p[0])):
                if p[i][j]:
                    out[r+i][s['c0']+j]=p[i][j]; occ[r+i][s['c0']+j]=True
    for s in sorted(frames,key=lambda s:(s['r0'],s['c0'])):
        for r in range(h-len(s['pat'])+1):
            if fits(r,s): put(r,s); break
    for s in sorted(crosses,key=lambda s:(-s['r0'],s['c0'])):
        for r in range(h-len(s['pat']),-1,-1):
            if fits(r,s): put(r,s); break
    return out

